module tb_TopModule;
    reg in1;
    reg in2;
    wire out;

    TopModule uut (
        .in1(in1),
        .in2(in2),
        .out(out)
    );

    initial begin
        integer i;
        for (i = 0; i < 4; i = i + 1) begin
            {in1, in2} = i[1:0];
            #10;
            // Expected: in1 & ~in2
            if (out !== (in1 & ~in2)) begin
                $display("SELFTEST FAIL: in1=%b, in2=%b, got=%b, expected=%b", in1, in2, out, (in1 & ~in2));
                $finish;
            end
        end
        $display("SELFTEST PASS");
        $finish;
    end
endmodule
